import{_ as o,o as t,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Projects — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Projects — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/projects"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Projects — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/projects"}]]},"headers":[],"relativePath":"deployment/projects.md","filePath":"deployment/projects.md","lastUpdated":1786752936000}'),s={name:"deployment/projects.md"};function n(i,e,c,d,l,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="projects-—-production-guide" tabindex="-1">Projects — Production Guide <a class="header-anchor" href="#projects-—-production-guide" aria-label="Permalink to &quot;Projects — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>projects</code></li><li>Category: <code>operations</code> (<strong>Operations</strong>), <code>category_sort_order = 40</code>, <code>sort_order = 10</code></li><li><strong>Free Marketplace opt-in</strong> module (not auto-installed)</li><li>Catalog flags: <code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code>, version <strong>1.0.0</strong></li><li><strong>No hard module dependency</strong> — Projects installs standalone; Contact / Company / Opportunity are optional soft links</li><li>Soft reverse link: Tasks may set <code>project_id</code> when Projects is entitled (Tasks catalog <strong>1.2.0</strong>)</li><li>New workspaces receive only <strong>Leads</strong> + <strong>Tasks</strong> (+ ToDos) by default; enable Projects from Marketplace at any time</li><li>Deactivate via Central module subscription tools to revoke access without dropping data</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create (Central tenant create or public register):</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules only (Projects is never auto-installed)</li><li>Operators enable <strong>Projects</strong> from Marketplace whenever needed — no prerequisite modules</li><li>Tenant permissions include <code>projects.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li></ol><p>No stage seeder — status defaults to <code>planned</code> at creation and advances via the state machine.</p><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Projects permissions for <strong>existing</strong> workspaces ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code>. Do <strong>not</strong> re-seed roles or rely on login/dashboard to repair RBAC.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>project_created</code>, <code>project_updated</code>, <code>project_deleted</code>, <code>project_assigned</code>, <code>project_members_synced</code>, <code>project_status_changed</code>, <code>project_note_added</code>, <code>project_restored</code></li><li>Notifications: assignment (<code>ProjectAssignedNotification</code>) and new member (<code>ProjectMemberAddedNotification</code>) — mail + database</li><li>Tenant mail settings with Central SMTP fallback</li><li>Dashboard widgets gated by <code>module:projects</code> + <code>projects.view</code></li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate project tables (<code>projects</code>, <code>project_members</code>, <code>project_notes</code>, <code>project_activities</code>)</li><li>Register the <code>projects</code> catalog module (migration, not seeder) as free opt-in under <code>operations</code> — <strong>no</strong> <code>module_dependencies</code> row</li><li>Migrate <code>projects.*</code> permissions and grant missing defaults to existing roles</li><li>Migrate <code>tasks.project_id</code> (nullable FK, null on project delete) and bump Tasks catalog <strong>1.1.2 → 1.2.0</strong></li><li>Confirm <code>module:projects</code> + <code>projects.*</code> on target roles</li><li>Deploy frontend (Projects nav under <strong>Workspace</strong>, after Tasks — board/list/form/detail; optional project picker on Tasks)</li><li>Smoke: create a <strong>new</strong> workspace → enable Projects alone → create/edit/assign/members/note → planned → active → on_hold → active → completed → soft delete/restore</li><li>Smoke (soft Task link): with Tasks + Projects → create a task with <code>project_id</code> → confirm embed; without Projects entitled → <code>project_id</code> validation fails</li><li>Smoke (overdue): set workspace timezone, open project with <code>ends_on</code> before local today → stats/dashboard <code>overdue_projects</code> increments; due today does not</li></ol><h2 id="roadmap-context" tabindex="-1">Roadmap context <a class="header-anchor" href="#roadmap-context" aria-label="Permalink to &quot;Roadmap context&quot;">​</a></h2><p>Projects ships as lean <strong>v1.0.0</strong> under Future Expansion / Operations. Gantt, milestones, task dependencies, workload heatmaps, Calendar projection, Automation <code>create_project</code>, tags, and <code>PRJ-</code> numbers remain deferred. See <a href="/architecture/module-dependencies">module-dependencies.md</a> and <a href="/getting-started/product-roadmap">product-roadmap.md</a>.</p>',15)])])}const g=o(s,[["render",n]]);export{u as __pageData,g as default};
